import { Injectable } from '@nestjs/common';
import { Database } from 'sqlite3';
import { open } from 'sqlite';
import * as bcrypt from 'bcrypt';
import * as jwt from 'jsonwebtoken';

@Injectable()
export class AppService {
  private db: Database;

  constructor() {
    this.initDb();
  }

  private async initDb() {
    this.db = await open({
      filename: 'db.sqlite3',
      driver: require('sqlite3').Database,
    });
    await this.db.exec(`CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      email TEXT UNIQUE,
      username TEXT,
      password TEXT
    )`);
    await this.db.exec(`CREATE TABLE IF NOT EXISTS secrets (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT,
      secret TEXT
    )`);
  }

  async register(email: string, username: string, password: string) {
    try {
      const hashedPassword = await bcrypt.hash(password, 10);
      await this.db.run('INSERT INTO users (email, username, password) VALUES (?, ?, ?)', [email, username, hashedPassword]);
      return { status: HttpStatus.CREATED, message: 'Registration successful' };
    } catch (error) {
      return { status: HttpStatus.BAD_REQUEST, message: 'Email already in use or invalid data' };
    }
  }

  async login(email: string, password: string) {
    const user = await this.db.get('SELECT * FROM users WHERE email = ?', [email]);
    if (user && await bcrypt.compare(password, user.password)) {
      const token = jwt.sign({ username: user.username }, process.env.APP_SECRET, { expiresIn: '1h' });
      return { status: HttpStatus.OK, token, message: 'Login successful' };
    }
    return { status: HttpStatus.UNAUTHORIZED, message: 'Invalid email or password' };
  }

  async setSecret(username: string, secret: string) {
    const user = await this.db.get('SELECT * FROM users WHERE username = ?', [username]);
    if (!user) {
      return { status: HttpStatus.UNAUTHORIZED, message: 'Invalid authentication token' };
    }
    await this.db.run('INSERT INTO secrets (username, secret) VALUES (?, ?)', [username, secret]);
    return { status: HttpStatus.OK, message: 'Secret has been set successfully' };
  }

  async getSecret(username: string) {
    const secret = await this.db.get('SELECT secret FROM secrets WHERE username = ?', [username]);
    if (secret) {
      return { status: HttpStatus.OK, secret: secret.secret };
    }
    return { status: HttpStatus.NOT_FOUND, message: 'Secret not found' };
  }
}
